"""mangui guides, batch 15 (extra tools): ffmpeg, sox, chisel, proxychains4, radare2, ROPgadget, ldapsearch, rpcclient.
Examples teach (command + explanation); nothing is captured. Written by scripts/mangui_write.py.
Option lists were written from knowledge, not checked against Kali's pages (run `mangui.py coverage` on Kali).
Use these tools only on systems and data you own or are explicitly authorised to test."""

GUIDES = []

# ============================================================== ffmpeg
