# ============================================================== ROPgadget
GUIDES.append(dict(
    name="ROPgadget", section="1", one_line="find ROP gadgets (useful code snippets) inside a binary",
    plain=["`ROPgadget` searches a program for short instruction sequences that end in a return (`ret`). Each one is a gadget. In a return-oriented programming (ROP) exercise you chain gadgets so the program runs code you choose, even when the stack is not executable (NX).",
           "A typical need: a `pop rdi ; ret` gadget to load the first argument on 64-bit Linux, then a call to `system`. ROPgadget finds the address of that gadget. Use it only on binaries from your own lab or a CTF."],
    when=["A pwn challenge has NX on, so you cannot run shellcode from the stack.", "You need the address of `pop rdi ; ret` or `syscall ; ret`.", "You want to find a string like `/bin/sh` inside the binary.", "You want to list every gadget and search it."],
    examples=[("List all gadgets", "ROPgadget --binary ./vuln", "Prints every gadget with its address. The list is long; pipe it to grep."),
              ("Find one gadget", "ROPgadget --binary ./vuln | grep 'pop rdi ; ret'", "Gives the address that loads the first function argument from the stack on x86-64."),
              ("Only certain gadgets", "ROPgadget --binary ./vuln --only 'pop|ret'", "--only keeps gadgets made of just those instructions: short, clean ones."),
              ("Search for a string", "ROPgadget --binary ./vuln --string '/bin/sh'", "Prints the address of the text in the binary if it is there."),
              ("Look in a library", "ROPgadget --binary /lib/x86_64-linux-gnu/libc.so.6 --only 'pop|ret' | grep rdi", "Libc has far more gadgets; remember to add its load address (leak it first)."),
              ("Avoid bad bytes", "ROPgadget --binary ./vuln --badbytes '00|0a'", "Hides gadgets whose address contains bytes your input cannot carry (a null byte or newline)."),
              ("Auto-build a chain", "ROPgadget --binary ./vuln --ropchain", "Tries to build a ready-made execve chain. It works only on simple cases; learn to build chains by hand with pwntools.")],
    options=[
        ("--binary FILE", "The program or library to search.", "Always."),
        ("--only 'a|b'", "Keep only gadgets made of these instructions.", "Short, clean gadgets."),
        ("--filter 'a|b'", "Remove gadgets that contain these instructions.", "Dropping risky ones."),
        ("--string TEXT", "Find the address of a string.", "/bin/sh."),
        ("--opcode HEX", "Search for raw bytes.", "Exact byte patterns."),
        ("--memstr 'chars'", "Search for individual characters in memory.", "Building a string from scattered bytes."),
        ("--badbytes 'xx|yy'", "Exclude gadget addresses that contain these bytes.", "Null bytes, newlines."),
        ("--range START-END", "Only search this address range.", "Narrowing."),
        ("--depth N", "Maximum gadget length in instructions (default 10).", "Longer or shorter gadgets."),
        ("--ropchain", "Try to build a ROP chain.", "Quick attempts."),
        ("--all", "Do not remove duplicate gadgets.", "Seeing every copy."),
        ("--norop / --nojop / --nosys", "Skip ROP / JOP / SYS-type gadgets.", "Focusing the search."),
        ("--multibr", "Include gadgets with several branches.", "Rare."),
        ("--thumb / --rawArch ARCH / --rawMode MODE", "ARM Thumb, and raw files with an explicit architecture.", "Non-x86 or raw dumps."),
        ("--console", "Interactive console.", "Searching repeatedly."),
        ("--offset ADDR", "Add an offset to every address.", "PIE or libc base."),
        ("--version / -h", "Version / help.", "A reminder.")],
    mistakes=["Forgetting to add the library or PIE base: the addresses ROPgadget prints are file offsets plus the default base, not runtime addresses.", "Using an address with a null byte when the vulnerable function stops at a null (strcpy, gets).", "Trusting --ropchain on a real challenge: it fails often, so learn to build chains by hand.", "Searching a 32-bit binary for 64-bit gadgets (check with `file`)."],
    try_=["Find `pop rdi ; ret` in a lab binary and write its address down.", "Search a lab libc for `/bin/sh` with --string.", "Combine it with pwntools: print the gadget address and use it in a short ROP chain."],
    see_also="pwntools(7), ropper(1), gdb(1), checksec(1), objdump(1), radare2(1), one_gadget.", partial=True))

# ============================================================== ldapsearch
GUIDES.append(dict(
    name="ldapsearch", section="1", one_line="query an LDAP directory (such as Active Directory)",
    plain=["`ldapsearch` asks an LDAP server questions. LDAP is the directory service behind Active Directory: it holds users, groups, computers and policies. The shape is `ldapsearch -H ldap://SERVER -x -b BASE FILTER ATTRIBUTES`.",
           "Two ideas: the BASE is where in the directory tree you start (for example `dc=corp,dc=local`), and the FILTER says what to find (`(objectClass=user)`). Many servers allow an anonymous bind (no password) to read a little: a classic first enumeration step in a lab."],
    when=["List the naming contexts of a domain controller.", "Enumerate users, groups and computers with valid credentials.", "Find descriptions or notes that contain a password (a common CTF clue).", "Check whether anonymous access is allowed."],
    examples=[("Find the base DN", "ldapsearch -x -H ldap://10.10.10.2 -s base namingContexts", "-x is simple authentication (no SASL), -s base asks only about the root entry. namingContexts shows the base names to use next."),
              ("Anonymous search", "ldapsearch -x -H ldap://10.10.10.2 -b 'dc=corp,dc=local'", "Tries to read everything without a password. Often refused, sometimes a few entries come back."),
              ("List users", "ldapsearch -x -H ldap://10.10.10.2 -D 'corp\\alice' -w 'Passw0rd' -b 'dc=corp,dc=local' '(objectClass=user)' sAMAccountName description", "-D is the account, -w the password. The final words are attributes to show: names and descriptions (descriptions sometimes hold passwords)."),
              ("Clean output", "ldapsearch -LLL -x -H ldap://10.10.10.2 -b 'dc=corp,dc=local' '(objectClass=user)' sAMAccountName", "-LLL removes comments and version lines, leaving tidy entries you can parse."),
              ("One user", "ldapsearch -LLL -x -H ldap://10.10.10.2 -D 'alice@corp.local' -W -b 'dc=corp,dc=local' '(sAMAccountName=bob)'", "-W asks for the password without putting it in your shell history."),
              ("Groups and members", "ldapsearch -LLL -x -H ldap://10.10.10.2 -D 'alice@corp.local' -W -b 'dc=corp,dc=local' '(&(objectClass=group)(cn=Domain Admins))' member", "(&(A)(B)) means A and B. This lists who is in Domain Admins."),
              ("Encrypted connection", "ldapsearch -x -H ldaps://10.10.10.2 -D 'alice@corp.local' -W -b 'dc=corp,dc=local' '(cn=alice)'", "ldaps:// uses TLS; -ZZ on a plain ldap:// URL starts TLS and fails if it cannot.")],
    options=[
        ("-H URI", "Server address: ldap://host or ldaps://host.", "Always."),
        ("-x", "Simple authentication instead of SASL.", "Almost always in labs."),
        ("-D DN", "The account to bind as.", "Authenticated searches."),
        ("-w PASS / -W / -y FILE", "Password on the command line / prompt / from a file.", "Prefer -W or -y: -w shows in the process list."),
        ("-b BASE", "Search base.", "Always."),
        ("-s SCOPE", "base, one or sub (default sub).", "base for the root entry."),
        ("-LLL", "Plain LDIF with no comments.", "Parsing results."),
        ("-z N / -l N", "Size limit / time limit.", "Large directories."),
        ("-Z / -ZZ", "Start TLS (and require it).", "Encrypted connections."),
        ("-E EXT", "Search extension, such as paged results (pr=1000).", "Directories with many entries."),
        ("-o OPT", "Options such as nettimeout.", "Slow networks."),
        ("-f FILE", "Run a search for each line of a file.", "Batches."),
        ("-n", "Show what would be done without doing it.", "Testing."),
        ("-v / -d LEVEL", "Verbose / debug.", "Connection problems."),
        ("-M", "Manage DSA IT control.", "Rare."),
        ("FILTER", "The search filter, for example (objectClass=user) or (&(a=1)(b=2)).", "Choosing what to find."),
        ("ATTRIBUTES", "Which fields to print.", "Less noise.")],
    mistakes=["Using the wrong base DN: read namingContexts first.", "Putting a password with -w in the shell history: use -W.", "Forgetting the quotes around a filter, so the shell mangles the parentheses.", "Expecting anonymous binds to work on modern servers: most refuse them."],
    try_=["Ask a lab domain controller for its namingContexts.", "List sAMAccountName for every user and read the descriptions.", "Find the members of a privileged group.", "Compare the result with BloodHound's view of the same domain."],
    see_also="ldapadd(1), ldapmodify(1), ldapwhoami(1), nmap(1) (ldap-* scripts), bloodhound(1), impacket, rpcclient(1), smbclient(1).", partial=True))

# ============================================================== rpcclient
GUIDES.append(dict(
    name="rpcclient", section="1", one_line="talk to a Windows or Samba machine over MS-RPC",
    plain=["`rpcclient` connects to a Windows (or Samba) host over SMB and runs remote procedure calls: list users, groups and shares, read the password policy, translate names to SIDs. It is a staple of Windows enumeration in labs.",
           "A null session (empty user and password) is accepted by some old or misconfigured hosts. Modern ones refuse it; with valid credentials you can usually do much more."],
    when=["Enumerate domain users and groups.", "Read the password policy before any guessing.", "Look up a user's full details or their group memberships.", "List shares and server information."],
    examples=[("Null session", "rpcclient -U '' -N 10.10.10.5", "-U '' is an empty user, -N means no password. If it connects you land at an `rpcclient $>` prompt."),
              ("With credentials", "rpcclient -U 'corp\\alice%Passw0rd' 10.10.10.5", "The format is DOMAIN\\user%password. Use -U alice and type the password when asked to keep it out of the history."),
              ("One command, then exit", "rpcclient -U '' -N -c 'enumdomusers' 10.10.10.5", "-c runs a command and returns, good for scripts."),
              ("List users and groups", "enumdomusers\nenumdomgroups", "Prints names with their RIDs (numeric ids). The rid 0x1f4 is Administrator."),
              ("Details of one user", "queryuser 0x1f4\nquerygroupmem 0x200", "queryuser shows a user's full record; querygroupmem lists the members of a group by RID."),
              ("Password policy", "getdompwinfo", "Shows the minimum length and the lockout rules: read it before attempting any password guessing."),
              ("Domain info", "querydominfo\nlsaquery\nsrvinfo", "Domain name, SID and server details."),
              ("Names and SIDs", "lookupnames administrator\nlookupsids S-1-5-21-...-500", "Translates between account names and SIDs."),
              ("Shares", "netshareenumall", "Lists the shares the server offers.")],
    options=[
        ("-U USER[%PASS]", "User name (and password).", "Always."),
        ("-N", "No password.", "Null sessions."),
        ("-W DOMAIN", "Domain or workgroup.", "Domain accounts."),
        ("-c 'CMD; CMD'", "Run commands then exit.", "Scripts."),
        ("-p PORT", "TCP port.", "Non-standard SMB."),
        ("-I ADDR", "Server IP address.", "When the name does not resolve."),
        ("-k", "Use Kerberos authentication.", "Kerberos-only domains."),
        ("-A FILE", "Authentication file.", "Keeping the password out of the history."),
        ("-d LEVEL / -s FILE", "Debug level / use a smb.conf file.", "Troubleshooting."),
        ("enumdomusers / enumdomgroups", "List users / groups.", "First enumeration."),
        ("queryuser RID / querygroup RID / querygroupmem RID", "Details of a user / group / group members.", "Following up a name."),
        ("getdompwinfo / getusrdompwinfo RID", "Domain password policy / per-user policy.", "Before password attacks."),
        ("lookupnames / lookupsids", "Name to SID and back.", "Mapping accounts."),
        ("netshareenum / netshareenumall / netsharegetinfo", "Shares and details.", "Finding shares."),
        ("srvinfo / lsaquery / querydominfo", "Server, domain SID, domain information.", "Context."),
        ("enumprivs / lsaenumsid", "Privileges / SIDs known to the host.", "Privilege discovery."),
        ("help", "List every command at the prompt.", "Always.")],
    mistakes=["Expecting a null session to work on a current Windows host: try credentials, or another tool.", "Forgetting that RIDs are hex (0x1f4 not 1f4 when typed).", "Putting a password in -U in the shell history: set it interactively or use -A.", "Ignoring the password policy and locking accounts out in a lab you share."],
    try_=["Connect to a lab host with a null session and run srvinfo.", "Enumerate users and groups, then query the first three users.", "Read the password policy and write down the lockout threshold."],
    see_also="smbclient(1), enum4linux(1), ldapsearch(1), net(8), nmap(1) (smb-* scripts), impacket, crackmapexec / netexec.", partial=True))
